{
  "title": "Reservar un ejemplar en la web de la Biblioteca",
  "role": "Persona Socia de la Biblioteca",
  "action": "Reservar un ejemplar para recogerlo en el mostrador",
  "benefit": "Disponer de un ejemplar reservado en la Biblioteca para usarlo según mi conveniencia",
  "description": "Como persona socio de la Biblioteca Municipal de Villaficticia, quiero reservar un ejemplar a través de la web para que sea recogido en el mostrador de la biblioteca. Esto me permite administrar mejor mi tiempo, ya que no voy obligado a esperar a que el ejemplar llegue a la biblioteca en la que me encuentro",
  "business_goal": "Facilitar un sistema fácil y eficiente para hacer reservas de ejemplares en la web de la Biblioteca para que puedan ser recogidos en el mostrador, mejorando la experiencia del usuario en la Biblioteca Municipal de Villaficticia. Proporcionar transparencia y un feedback por reservas no recogidas",
  "scope_includes": [
    "Persona Socia de la Biblioteca",
    "Reservar un ejemplar a través de la web de la Biblioteca",
    "Recoger el ejemplar en el mostrador de la Biblioteca",
    "Estado de una reserva en la Biblioteca"
  ],
  "scope_excludes": [
    "Reservar un ejemplar a través de una aplicación móvil",
    "Reservar un ejemplar a través de otro sistema de la Biblioteca (por ejemplo, un dispositivo de auto-check-out)",
    "Recoger el ejemplar de la biblioteca de otro lugar que no sea el mostrador",
    "Tareas internas de la Biblioteca (como renovar un préstamo)"
  ],
  "acceptance_criteria": [
    {
      "id": "CA-01",
      "title": "Como administrador de la Biblioteca recibo una solicitud de reserva",
      "given": [
        "El administrador está loggeado en la web de la Biblioteca",
        "El administrador está en una etapa de reserva de ejemplar"
      ],
      "when": [
        "Recibe una solicitud de reserva para un ejemplar de texto",
        "La persona socio le ha enviado una solicitud de reservar ese ejemplar a través de la página web de la Biblioteca",
        "La persona socio ha introducido correctamente los datos necesarios para realizar la reserva en la web de la Biblioteca",
        "El administrador acepta la solicitud de reserva que ha pasado por el proceso de validación"
      ],
      "then": [
        "Se crea una nueva reserva en la base de datos de la Biblioteca",
        "Se notifica a la persona socio que su reserva ha sido aceptada",
        "El sistema recoge los datos de la persona socio para la identificación"
      ]
    },
    {
      "id": "CA-02",
      "title": "Como persona socio, ve mi reserva pendiente en la página web de la Biblioteca",
      "given": [
        "El administrador de la Biblioteca ha aceptado una reserva para el texto 'Primer Romance'", "La persona socio tiene abierto la página web de la Biblioteca y ha iniciado sesión con su cuenta de usuario",
        "La persona socio ha introducido correctamente los datos necesarios para confirmar que ha reservado el ejemplar de texto 'Primer Romance'"
      ],
      "when": [
        "Se ha ejecutado el proceso de validación de la solicitud de reserva",
        "La persona socio verifica que existe una reserva pendiente para el ejemplar de texto 'Primer Romance'",
        "La persona socio ha introducido correctamente los datos necesarios para revisar su reserva"
      ],
      "then": [
        "Se muestra en la página web de la Biblioteca la reserva pendiente para el ejemplar de texto 'Primer Romance'",
        "Se confirman los datos de la persona socio correspondientes al texto 'Primer Romance'",
        "La persona socio ve que el estado de la reserva es 'Pendiente'"
      ]
    },
    {
      "id": "CA-03",
      "title": "Como persona socio, ve la página de detalles de la reserva pendiente para un ejemplar en la web de la Biblioteca",
      "given": [
        "El administrador de la Biblioteca ha aceptado una reserva para el texto 'Primera novela'", "La persona socio ha accedido a la página web de la Biblioteca desde un dispositivo que puede utilizar con seguridad (por ejemplo, una computadora de escritorio)",
        "El administrador de la Biblioteca se ha asegurado de que la persona socio tiene acceso a la información necesaria, que es la URL de la página de detalles de la reserva pendiente para el ejemplar 'Primera novela'"
      ],
      "when": [
        "Se ha ejecutado el proceso de validación de la solicitud de reserva",
        "La persona socio ingresa en la URL de la página de detalles de la reserva para verificar la información",
        "La persona socio ingresa en la URL de la página de detalles desde el dispositivo que puede utilizar con seguridad"
      ],
      "then": [
        "Se muestra la página de detalles para su reserva pendiente en la Biblioteca",
        "Se establece la confianza del administrador en que la persona socio tiene la información requerida",
        "La persona socio ve la url de la página de detalles de su reserva pendiente",
        "La persona socio accede a las opciones para modificar la reserva de 'Primera novela'"
      ]
    },
    {
      "id": "CA-04",
      "title": "Como persona socio, ve que la reserva ha caducado y ve el aviso de la Biblioteca con información de la reserva de ejemplar que no ha sido recogida",
      "given": [
        "La persona socio ha reservado el texto 'Segundo Romance'", "La persona socio tiene abierto la página web de la Biblioteca y ha iniciado sesión con su cuenta de usuario",
        "La persona socio ha reservado el texto 'Segundo Romance' en un dispositivo de escritorio. Establece que la persona socio ha seguido todas las pauta de la reserva y cumple con las solicitudes de la persona socio",
        "La persona socio habla con la persona socio y ve que el ejemplar no ha sido recogido en los primeros 48 horas, por lo que la reserva caducará",
        "La persona socio ve que la página web de la Biblioteca tiene un botón para ver la página de registro de reservas no recogidas"
      ],
      "when": [
        "Se actualizó el estado de la reserva al pasar el tiempo",
        "Se habrá ejecutado el proceso de validación de la solicitud de reserva",
        "La página web de la Biblioteca ha detectado que la reserva para el texto 'Segundo Romance' ha caducado",
        "La persona socio hace clic en el botón para ver la página de registro de reservas no recogidas"
      ],
      "then": [
        "Se muestra en la página web de la Biblioteca la página que se ha establecido como la página de registro de reservas no recogidas",
        "Se establece la confianza del administrador en la persona socio y ha proporcionado ver información de esta reserva",
        "Se muestra la reserva 'Segundo Romance' que no ha sido recogida y se muestra información sobre ello, que se ha establecido en el sistema de la Biblioteca",
        "La persona socio ve las fechas para recoger la reserva"
      ]
    }
  ],
  "business_rules": [
    {
      "id": "RN-RES-01",
      "description": "Sólo pueden reservar las personas socias con carné vigente y sin sanción activa. Para más información, ver DOC-02, Reglamento de reservas, Cláusula 2, RN-SAN-03 y RN-SAN-04."
